package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.type.TypeFactory;
import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Collections;
import java.util.List;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.ArgumentMatchers.isNull;
import static org.mockito.Mockito.*;

public class TypeParser_parseType_TriageGen0Test {

    private TypeFactory typeFactory;
    private TypeParser typeParser;
    private MyTokenizer mockTokens;

    // Subclass to expose protected method for testing
    private static class TestableTypeParser extends TypeParser {
        protected TestableTypeParser(TypeFactory f) {
            super(f);
        }

        @Override
        protected Class<?> findClass(String className, MyTokenizer tokens) {
            if ("String".equals(className)) return String.class;
            if ("List".equals(className)) return java.util.List.class;
            return null;
        }

        @Override
        protected List<JavaType> parseTypes(MyTokenizer tokens) throws IllegalArgumentException {
            // Simplified mock behavior for parseTypes
            return Collections.singletonList(typeFactory.constructType(String.class));
        }

        @Override
        protected IllegalArgumentException _problem(MyTokenizer tokens, String msg) {
            return new IllegalArgumentException(msg);
        }

        // Accessor for the protected method under test
        public JavaType callParseType(MyTokenizer tokens) throws IllegalArgumentException {
            return super.parseType(tokens);
        }
    }

    @Before
    public void setUp() {
        typeFactory = TypeFactory.defaultInstance();
        typeParser = new TestableTypeParser(typeFactory);
        mockTokens = mock(MyTokenizer.class);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseType_UnexpectedEndOfString() throws IllegalArgumentException {
        when(mockTokens.hasMoreTokens()).thenReturn(false);
        typeParser.callParseType(mockTokens);
    }

    @Test
    public void testParseType_SimpleClass() throws IllegalArgumentException {
        when(mockTokens.hasMoreTokens()).thenReturn(true, false);
        when(mockTokens.nextToken()).thenReturn("String");

        JavaType result = typeParser.callParseType(mockTokens);

        assertNotNull(result);
        assertEquals(String.class, result.getRawClass());
    }

    @Test
    public void testParseType_GenericType() throws IllegalArgumentException {
        // Sequence: hasMore(true) -> nextToken("List") -> hasMore(true) -> nextToken("<") -> hasMore(true) [for parseTypes]
        when(mockTokens.hasMoreTokens()).thenReturn(true, true, true);
        when(mockTokens.nextToken()).thenReturn("List", "<");

        JavaType result = typeParser.callParseType(mockTokens);

        assertNotNull(result);
        assertEquals(java.util.List.class, result.getRawClass());
        // Verify that parseTypes was implicitly called via the logic flow
        verify(mockTokens).nextToken();
    }

    @Test
    public void testParseType_CommaOrClosingBracket() throws IllegalArgumentException {
        // Scenario: tokens.nextToken() returns something that is NOT "<"
        // It should push back the token and return the base class
        when(mockTokens.hasMoreTokens()).thenReturn(true, true);
        when(mockTokens.nextToken()).thenReturn("String", ",");

        JavaType result = typeParser.callParseType(mockTokens);

        assertNotNull(result);
        assertEquals(String.class, result.getRawClass());
        verify(mockTokens).pushBack(",");
    }

    @Test
    public void testParseType_WithNullBaseClass() throws IllegalArgumentException {
        // Scenario where findClass returns null
        when(mockTokens.hasMoreTokens()).thenReturn(true, false);
        when(mockTokens.nextToken()).thenReturn("NonExistentClass");

        JavaType result = typeParser.callParseType(mockTokens);

        assertNotNull(result);
        assertEquals(null, result.getRawClass());
    }
}
